import{_ as e,o,c as i,ag as r}from"./chunks/framework.7He2WLS4.js";const c=JSON.parse('{"title":"Simulating Slow Networks","description":"","frontmatter":{},"headers":[],"relativePath":"guides/simulating-slow-networks.md","filePath":"guides/simulating-slow-networks.md","lastUpdated":1772297611000}'),s={name:"guides/simulating-slow-networks.md"};function a(n,t,l,d,g,p){return o(),i("div",null,[...t[0]||(t[0]=[r('<h1 id="simulating-slow-networks" tabindex="-1">Simulating Slow Networks <a class="header-anchor" href="#simulating-slow-networks" aria-label="Permalink to &quot;Simulating Slow Networks&quot;">​</a></h1><p><strong>Difficulty:</strong> Beginner | <strong>Time:</strong> 10 minutes</p><p>This tutorial shows you how to use NectoProxy&#39;s network conditioning feature to simulate slow, unreliable, or constrained network connections. This helps you understand how your application behaves for users on mobile networks, slow Wi-Fi, or in regions with poor connectivity.</p><h2 id="prerequisites" tabindex="-1">Prerequisites <a class="header-anchor" href="#prerequisites" aria-label="Permalink to &quot;Prerequisites&quot;">​</a></h2><ul><li>NectoProxy installed and running</li><li>Browser configured to use the proxy (port 8888)</li></ul><h2 id="why-simulate-slow-networks" tabindex="-1">Why Simulate Slow Networks? <a class="header-anchor" href="#why-simulate-slow-networks" aria-label="Permalink to &quot;Why Simulate Slow Networks?&quot;">​</a></h2><p>Most developers work on fast, reliable connections. Your users may not. Network simulation helps you:</p><ul><li>Test loading states and skeleton screens</li><li>Verify progressive image loading</li><li>Ensure lazy loading works correctly</li><li>Check that timeouts are configured properly</li><li>Measure perceived performance</li><li>Test offline handling</li></ul><h2 id="step-1-open-the-network-conditioning-panel" tabindex="-1">Step 1: Open the Network Conditioning Panel <a class="header-anchor" href="#step-1-open-the-network-conditioning-panel" aria-label="Permalink to &quot;Step 1: Open the Network Conditioning Panel&quot;">​</a></h2><p>In the NectoProxy Web UI, click the <strong>Network Conditioning</strong> button in the header toolbar (the speedometer/gauge icon). This opens the Network Conditioning panel.</p><h2 id="step-2-select-a-built-in-preset" tabindex="-1">Step 2: Select a Built-In Preset <a class="header-anchor" href="#step-2-select-a-built-in-preset" aria-label="Permalink to &quot;Step 2: Select a Built-In Preset&quot;">​</a></h2><p>NectoProxy includes several built-in network presets that model real-world connections:</p><table tabindex="0"><thead><tr><th>Preset</th><th>Download</th><th>Upload</th><th>Latency</th><th>Packet Loss</th></tr></thead><tbody><tr><td><strong>No Throttling</strong></td><td>Unlimited</td><td>Unlimited</td><td>0 ms</td><td>0%</td></tr><tr><td><strong>Slow 2G</strong></td><td>280 Kbps</td><td>256 Kbps</td><td>1,400 ms</td><td>1%</td></tr><tr><td><strong>Regular 2G</strong></td><td>450 Kbps</td><td>150 Kbps</td><td>800 ms</td><td>0.5%</td></tr><tr><td><strong>Good 2G</strong></td><td>900 Kbps</td><td>280 Kbps</td><td>650 ms</td><td>0.2%</td></tr><tr><td><strong>Slow 3G</strong></td><td>780 Kbps</td><td>330 Kbps</td><td>400 ms</td><td>0%</td></tr><tr><td><strong>Regular 3G</strong></td><td>1.5 Mbps</td><td>750 Kbps</td><td>300 ms</td><td>0%</td></tr><tr><td><strong>Good 3G</strong></td><td>4 Mbps</td><td>1.5 Mbps</td><td>170 ms</td><td>0%</td></tr><tr><td><strong>Regular 4G</strong></td><td>9 Mbps</td><td>4 Mbps</td><td>50 ms</td><td>0%</td></tr><tr><td><strong>DSL</strong></td><td>2 Mbps</td><td>1 Mbps</td><td>50 ms</td><td>0%</td></tr><tr><td><strong>WiFi</strong></td><td>30 Mbps</td><td>15 Mbps</td><td>10 ms</td><td>0%</td></tr><tr><td><strong>Offline</strong></td><td>~0</td><td>~0</td><td>30,000 ms</td><td>100%</td></tr></tbody></table><p>To activate a preset:</p><ol><li>Click on the preset name in the list.</li><li>The preset is applied immediately to all traffic flowing through the proxy.</li><li>An indicator appears in the header showing that network conditioning is active.</li></ol><div class="tip custom-block"><p class="custom-block-title">TIP</p><p>Start with <strong>Slow 3G</strong> for a realistic representation of a poor-but-usable mobile connection. This is the condition most likely to reveal performance issues in your application.</p></div><h2 id="step-3-browse-your-application" tabindex="-1">Step 3: Browse Your Application <a class="header-anchor" href="#step-3-browse-your-application" aria-label="Permalink to &quot;Step 3: Browse Your Application&quot;">​</a></h2><p>With network conditioning active, open your application in the browser and interact with it normally. Pay attention to:</p><ul><li><strong>Initial load time:</strong> How long does the page take to become usable?</li><li><strong>Navigation:</strong> Are page transitions smooth, or do they freeze while loading?</li><li><strong>Images:</strong> Do images load progressively or suddenly appear after a long wait?</li><li><strong>API calls:</strong> Are loading spinners shown while data is being fetched?</li><li><strong>Forms:</strong> Does submitting a form feel responsive, or does the user wonder if it worked?</li></ul><h2 id="step-4-create-a-custom-network-profile" tabindex="-1">Step 4: Create a Custom Network Profile <a class="header-anchor" href="#step-4-create-a-custom-network-profile" aria-label="Permalink to &quot;Step 4: Create a Custom Network Profile&quot;">​</a></h2><p>If the built-in presets do not match your specific needs, create a custom profile:</p><ol><li><p>In the Network Conditioning panel, look for the option to create a custom profile.</p></li><li><p>Configure the following parameters:</p><table tabindex="0"><thead><tr><th>Parameter</th><th>Description</th><th>Unit</th></tr></thead><tbody><tr><td><strong>Download Bandwidth</strong></td><td>Maximum download speed</td><td>bytes/second</td></tr><tr><td><strong>Upload Bandwidth</strong></td><td>Maximum upload speed</td><td>bytes/second</td></tr><tr><td><strong>Latency</strong></td><td>Base round-trip delay added to each request</td><td>milliseconds</td></tr><tr><td><strong>Latency Jitter</strong></td><td>Random variance added to the base latency</td><td>milliseconds</td></tr><tr><td><strong>Packet Loss</strong></td><td>Percentage of requests randomly dropped</td><td>0-100%</td></tr></tbody></table></li></ol><details class="details custom-block"><summary>Example: Australian Rural Connection</summary><p>To simulate a connection typical of rural Australia:</p><table tabindex="0"><thead><tr><th>Parameter</th><th>Value</th></tr></thead><tbody><tr><td>Download Bandwidth</td><td>128 KB/s (1 Mbps)</td></tr><tr><td>Upload Bandwidth</td><td>32 KB/s (256 Kbps)</td></tr><tr><td>Latency</td><td>200 ms</td></tr><tr><td>Latency Jitter</td><td>50 ms</td></tr><tr><td>Packet Loss</td><td>0.5%</td></tr></tbody></table></details><h2 id="step-5-test-progressive-image-loading" tabindex="-1">Step 5: Test Progressive Image Loading <a class="header-anchor" href="#step-5-test-progressive-image-loading" aria-label="Permalink to &quot;Step 5: Test Progressive Image Loading&quot;">​</a></h2><p>Progressive images are loaded in stages, providing a blurry preview first and progressively improving quality. To test this:</p><ol><li>Select the <strong>Slow 3G</strong> or <strong>Regular 2G</strong> preset.</li><li>Navigate to a page with images.</li><li>Observe whether images: <ul><li>Show a placeholder/skeleton while loading (good)</li><li>Appear all at once after a long delay (needs improvement)</li><li>Load progressively from blurry to sharp (ideal for JPEG)</li></ul></li></ol><h2 id="step-6-test-lazy-loading-behavior" tabindex="-1">Step 6: Test Lazy Loading Behavior <a class="header-anchor" href="#step-6-test-lazy-loading-behavior" aria-label="Permalink to &quot;Step 6: Test Lazy Loading Behavior&quot;">​</a></h2><p>Lazy loading defers loading of off-screen content until the user scrolls to it. To test:</p><ol><li>Activate a slow network preset (e.g., <strong>Slow 3G</strong>).</li><li>Navigate to a page with a long scrollable list.</li><li>Scroll slowly and observe: <ul><li>Are off-screen items loaded on demand?</li><li>Is there a visible loading state when new items appear?</li><li>Does the scrolling feel janky due to layout shifts?</li><li>Does infinite scroll work correctly under slow conditions?</li></ul></li></ol><h2 id="combining-global-conditioning-with-per-url-throttle-rules" tabindex="-1">Combining Global Conditioning with Per-URL Throttle Rules <a class="header-anchor" href="#combining-global-conditioning-with-per-url-throttle-rules" aria-label="Permalink to &quot;Combining Global Conditioning with Per-URL Throttle Rules&quot;">​</a></h2><p>For more targeted testing, combine global network conditioning with per-URL throttle rules:</p><p><strong>Global conditioning</strong> affects all traffic uniformly. <strong>Throttle rules</strong> let you apply specific bandwidth limits to individual URLs.</p><p><strong>Example scenario:</strong> You want to test your app with generally fast internet but a slow image CDN:</p><ol><li><p>Keep global network conditioning set to <strong>No Throttling</strong> (or a fast profile like <strong>WiFi</strong>).</p></li><li><p>Create a <strong>Throttle rule</strong> in the Rules panel:</p><table tabindex="0"><thead><tr><th>Field</th><th>Value</th></tr></thead><tbody><tr><td><strong>Name</strong></td><td>Slow Image CDN</td></tr><tr><td><strong>Action</strong></td><td>Throttle</td></tr><tr><td><strong>Match Host</strong></td><td><code>cdn.example.com</code></td></tr><tr><td><strong>Bytes Per Second</strong></td><td><code>51200</code> (50 KB/s)</td></tr><tr><td><strong>Latency</strong></td><td><code>500</code> (ms)</td></tr></tbody></table></li></ol><p>This way, your API calls remain fast while images from the CDN load slowly, accurately simulating a scenario where the CDN is under load or geographically distant.</p><h2 id="tips-for-network-simulation-testing" tabindex="-1">Tips for Network Simulation Testing <a class="header-anchor" href="#tips-for-network-simulation-testing" aria-label="Permalink to &quot;Tips for Network Simulation Testing&quot;">​</a></h2><ul><li><strong>Test the &quot;first visit&quot; experience:</strong> Clear your browser cache before testing with slow networks. Cached resources skew results.</li><li><strong>Monitor the NectoProxy traffic list</strong> to see actual transfer times for each request. The duration column shows how long each request took under the simulated conditions.</li><li><strong>Use the &quot;Offline&quot; preset</strong> to test what happens when the network is completely unavailable. Your app should detect this and show an appropriate message.</li><li><strong>Test on actual mobile devices</strong> by combining network conditioning with the <a href="./debugging-mobile.html">mobile debugging setup</a>. This gives you a more realistic picture than emulating mobile conditions in a desktop browser.</li><li><strong>Measure Core Web Vitals</strong> under constrained conditions. A page that scores well on a fast connection may perform poorly on 3G.</li></ul><div class="warning custom-block"><p class="custom-block-title">WARNING</p><p>Remember to disable network conditioning when you are done testing. Leaving it active will slow down all traffic through the proxy, including your regular browsing.</p></div>',38)])])}const u=e(s,[["render",a]]);export{c as __pageData,u as default};
